<script setup lang="ts">import {executeSql,type SqlResult} from "@/api/maintenance";import {message} from "@/utils/message";import {computed,ref} from "vue";defineOptions({name:"SqlConsole"});const sql=ref("select name from sqlite_master where type = 'table'"),loading=ref(false),result=ref<SqlResult>();const dangerous=computed(()=>!/^(select|with|explain|pragma)\b/i.test(sql.value.trim()));const run=async()=>{loading.value=true;try{result.value=(await executeSql(sql.value,dangerous.value)).data;message("SQL 已执行",{type:"success"});}finally{loading.value=false;}};</script><template><div class="page-root"><el-card shadow="never"><template #header>SQL 执行台（仅本地开发）</template><el-alert type="warning" :closable="false" title="查询最多返回 100 行；写入或 DDL 操作需要再次确认，敏感字段会脱敏。" class="mb-4"/><el-input v-model="sql" type="textarea" :rows="10" class="font-mono"/><div class="mt-3"><el-popconfirm v-if="dangerous" title="确认执行危险 SQL？" @confirm="run"><template #reference><el-button type="danger" :loading="loading">确认执行</el-button></template></el-popconfirm><el-button v-else type="primary" :loading="loading" @click="run">执行查询</el-button></div><el-table v-if="result?.query" :data="result.rows" class="mt-4"><el-table-column v-for="key in Object.keys(result.rows[0]||{})" :key="key" :prop="key" :label="key"/></el-table><el-result v-else-if="result" icon="success" title="执行完成" :sub-title="`影响 ${result.updateCount} 行`"/></el-card></div></template>
